// 黄金矿工钩子状态机实现

// 状态枚举
enum HookState {
  IDLE = 'IDLE',           // 待命状态
  SWINGING = 'SWINGING',   // 摆动状态
  FIRING = 'FIRING',       // 发射状态
  RETRACTING = 'RETRACTING', // 回收状态
  GRABBING = 'GRABBING'    // 抓取中状态
}

// 抓取物品接口
interface GrabbedItem {
  id: string;
  type: 'gold' | 'diamond' | 'rock' | 'empty';
  weight: number;
  value: number;
}

// 钩子配置
interface HookConfig {
  swingAngle: number;        // 摆动角度
  swingSpeed: number;        // 摆动速度
  fireSpeed: number;         // 发射速度
  retractSpeed: number;      // 基础回收速度
  maxLength: number;         // 最大长度
}

// 状态机事件
type HookEvent = 
  | { type: 'FIRE' } 
  | { type: 'HIT_ITEM'; item: GrabbedItem }
  | { type: 'HIT_BOUNDARY' }
  | { type: 'RETRACT_COMPLETE' }
  | { type: 'RESET' };

// 钩子状态机类
class HookStateMachine {
  private state: HookState = HookState.IDLE;
  private currentAngle: number = 0;
  private hookLength: number = 0;
  private grabbedItem: GrabbedItem | null = null;
  private swingDirection: number = 1; // 1: 右, -1: 左
  private config: HookConfig;
  private onStateChange?: (state: HookState) => void;
  private onItemGrabbed?: (item: GrabbedItem) => void;

  constructor(config: Partial<HookConfig> = {}) {
    this.config = {
      swingAngle: 80,
      swingSpeed: 2,
      fireSpeed: 8,
      retractSpeed: 5,
      maxLength: 400,
      ...config
    };
  }

  // 设置状态变更回调
  setStateChangeCallback(callback: (state: HookState) => void): void {
    this.onStateChange = callback;
  }

  // 设置抓取回调
  setItemGrabbedCallback(callback: (item: GrabbedItem) => void): void {
    this.onItemGrabbed = callback;
  }

  // 获取当前状态
  getState(): HookState {
    return this.state;
  }

  // 获取当前角度
  getAngle(): number {
    return this.currentAngle;
  }

  // 获取钩子长度
  getLength(): number {
    return this.hookLength;
  }

  // 获取抓取物品
  getGrabbedItem(): GrabbedItem | null {
    return this.grabbedItem;
  }

  // 状态转换
  private transition(newState: HookState): void {
    this.exitState(this.state);
    const oldState = this.state;
    this.state = newState;
    this.enterState(newState);

    console.log(`[状态转换] ${oldState} -> ${newState}`);
    this.onStateChange?.(newState);
  }

  // 进入状态逻辑
  private enterState(state: HookState): void {
    switch (state) {
      case HookState.IDLE:
        this.enterIdle();
        break;
      case HookState.SWINGING:
        this.enterSwinging();
        break;
      case HookState.FIRING:
        this.enterFiring();
        break;
      case HookState.RETRACTING:
        this.enterRetracting();
        break;
      case HookState.GRABBING:
        this.enterGrabbing();
        break;
    }
  }

  // 退出状态逻辑
  private exitState(state: HookState): void {
    switch (state) {
      case HookState.IDLE:
        this.exitIdle();
        break;
      case HookState.SWINGING:
        this.exitSwinging();
        break;
      case HookState.FIRING:
        this.exitFiring();
        break;
      case HookState.RETRACTING:
        this.exitRetracting();
        break;
      case HookState.GRABBING:
        this.exitGrabbing();
        break;
    }
  }

  // ========== 各状态的进入/退出逻辑 ==========

  // 待命状态
  private enterIdle(): void {
    this.hookLength = 0;
    this.grabbedItem = null;
    console.log('[待命] 钩子已重置，等待玩家操作');
  }

  private exitIdle(): void {
    console.log('[待命退出] 准备开始摆动');
  }

  // 摆动状态
  private enterSwinging(): void {
    console.log('[摆动] 钩子开始左右摆动');
  }

  private exitSwinging(): void {
    console.log('[摆动退出] 钩子停止摆动');
  }

  // 发射状态
  private enterFiring(): void {
    console.log(`[发射] 钩子以角度 ${this.currentAngle}° 向下发射`);
  }

  private exitFiring(): void {
    console.log('[发射退出] 钩子停止发射');
  }

  // 回收状态（空手）
  private enterRetracting(): void {
    console.log('[回收] 钩子空手回收中');
  }

  private exitRetracting(): void {
    console.log('[回收退出] 钩子已回到起点');
  }

  // 抓取中状态
  private enterGrabbing(): void {
    if (this.grabbedItem) {
      console.log(`[抓取中] 正在拉取 ${this.grabbedItem.type}，重量: ${this.grabbedItem.weight}`);
    }
  }

  private exitGrabbing(): void {
    if (this.grabbedItem) {
      console.log(`[抓取退出] 成功获取 ${this.grabbedItem.type}，价值: ${this.grabbedItem.value}`);
      this.onItemGrabbed?.(this.grabbedItem);
    }
  }

  // ========== 更新逻辑 ==========

  // 主更新循环
  update(deltaTime: number): void {
    switch (this.state) {
      case HookState.SWINGING:
        this.updateSwinging(deltaTime);
        break;
      case HookState.FIRING:
        this.updateFiring(deltaTime);
        break;
      case HookState.RETRACTING:
        this.updateRetracting(deltaTime);
        break;
      case HookState.GRABBING:
        this.updateGrabbing(deltaTime);
        break;
    }
  }

  // 摆动更新
  private updateSwinging(deltaTime: number): void {
    this.currentAngle += this.config.swingSpeed * this.swingDirection * deltaTime;

    // 边界检查：到达最大摆动角度时反向
    if (this.currentAngle >= this.config.swingAngle) {
      this.currentAngle = this.config.swingAngle;
      this.swingDirection = -1;
    } else if (this.currentAngle <= -this.config.swingAngle) {
      this.currentAngle = -this.config.swingAngle;
      this.swingDirection = 1;
    }
  }

  // 发射更新
  private updateFiring(deltaTime: number): void {
    this.hookLength += this.config.fireSpeed * deltaTime;

    // 边界检查：达到最大长度
    if (this.hookLength >= this.config.maxLength) {
      this.hookLength = this.config.maxLength;
      this.transition(HookState.RETRACTING);
    }
  }

  // 回收更新（空手）
  private updateRetracting(deltaTime: number): void {
    this.hookLength -= this.config.retractSpeed * deltaTime;

    // 边界检查：回收完成
    if (this.hookLength <= 0) {
      this.hookLength = 0;
      this.transition(HookState.SWINGING);
    }
  }

  // 抓取更新（带物品）
  private updateGrabbing(deltaTime: number): void {
    if (!this.grabbedItem) {
      this.transition(HookState.RETRACTING);
      return;
    }

    // 根据物品重量调整回收速度
    const weightFactor = 1 / (1 + this.grabbedItem.weight * 0.1);
    const adjustedSpeed = this.config.retractSpeed * weightFactor;

    this.hookLength -= adjustedSpeed * deltaTime;

    // 边界检查：回收完成
    if (this.hookLength <= 0) {
      this.hookLength = 0;
      this.transition(HookState.IDLE);
    }
  }

  // ========== 事件处理 ==========

  // 处理事件
  handleEvent(event: HookEvent): void {
    console.log(`[事件] ${event.type}`);

    switch (event.type) {
      case 'FIRE':
        this.handleFireEvent();
        break;
      case 'HIT_ITEM':
        this.handleHitItemEvent(event.item);
        break;
      case 'HIT_BOUNDARY':
        this.handleHitBoundaryEvent();
        break;
      case 'RETRACT_COMPLETE':
        this.handleRetractCompleteEvent();
        break;
      case 'RESET':
        this.handleResetEvent();
        break;
    }
  }

  private handleFireEvent(): void {
    if (this.state === HookState.SWINGING) {
      this.transition(HookState.FIRING);
    } else {
      console.warn(`[警告] 无法在 ${this.state} 状态下发射`);
    }
  }

  private handleHitItemEvent(item: GrabbedItem): void {
    if (this.state === HookState.FIRING) {
      this.grabbedItem = item;
      this.transition(HookState.GRABBING);
    }
  }

  private handleHitBoundaryEvent(): void {
    if (this.state === HookState.FIRING) {
      this.transition(HookState.RETRACTING);
    }
  }

  private handleRetractCompleteEvent(): void {
    // 此事件通常由update自动处理，这里作为备用
    if (this.state === HookState.RETRACTING || this.state === HookState.GRABBING) {
      this.transition(HookState.IDLE);
    }
  }

  private handleResetEvent(): void {
    console.log('[重置] 强制重置状态机');
    this.currentAngle = 0;
    this.hookLength = 0;
    this.grabbedItem = null;
    this.swingDirection = 1;
    this.transition(HookState.IDLE);
  }

  // ========== 外部接口 ==========

  // 开始游戏（进入摆动）
  start(): void {
    this.transition(HookState.SWINGING);
  }

  // 发射钩子
  fire(): void {
    this.handleEvent({ type: 'FIRE' });
  }

  // 模拟碰撞检测
  simulateCollision(item: GrabbedItem | null): void {
    if (item) {
      this.handleEvent({ type: 'HIT_ITEM', item });
    } else {
      this.handleEvent({ type: 'HIT_BOUNDARY' });
    }
  }

  // 重置
  reset(): void {
    this.handleEvent({ type: 'RESET' });
  }
}

// ========== 测试代码 ==========

// 创建状态机实例
const hook = new HookStateMachine({
  swingAngle: 75,
  swingSpeed: 3,
  fireSpeed: 10,
  retractSpeed: 6,
  maxLength: 350
});

// 设置回调
hook.setStateChangeCallback((state) => {
  console.log(`>>> 状态已变更: ${state}`);
});

hook.setItemGrabbedCallback((item) => {
  console.log(`>>> 获得物品: ${item.type}, 价值: ${item.value}`);
});

// 测试流程
console.log('\n========== 开始测试 ==========\n');

// 启动游戏
hook.start();

// 模拟摆动
console.log('\n--- 模拟摆动 ---');
for (let i = 0; i < 10; i++) {
  hook.update(0.1);
  console.log(`角度: ${hook.getAngle().toFixed(1)}°`);
}

// 发射钩子
console.log('\n--- 发射钩子 ---');
hook.fire();

// 模拟发射过程
console.log('\n--- 模拟发射 ---');
for (let i = 0; i < 20; i++) {
  hook.update(0.1);
  console.log(`长度: ${hook.getLength().toFixed(1)}`);

  // 模拟在第10次时抓到金块
  if (i === 10) {
    hook.simulateCollision({
      id: 'gold_1',
      type: 'gold',
      weight: 3,
      value: 100
    });
  }
}

// 模拟抓取回收
console.log('\n--- 模拟抓取回收 ---');
while (hook.getState() !== HookState.IDLE) {
  hook.update(0.1);
  console.log(`长度: ${hook.getLength().toFixed(1)}, 状态: ${hook.getState()}`);
}

// 测试边界情况：抓到大石头
console.log('\n--- 测试大石头 ---');
hook.start();
hook.fire();
hook.simulateCollision({
  id: 'rock_big',
  type: 'rock',
  weight: 10,
  value: 5
});

while (hook.getState() !== HookState.IDLE) {
  hook.update(0.1);
  console.log(`拉取大石头中... 长度: ${hook.getLength().toFixed(1)}`);
}

// 测试重置
console.log('\n--- 测试重置 ---');
hook.start();
hook.fire();
hook.reset();

console.log('\n========== 测试完成 ==========\n');
console.log(`最终状态: ${hook.getState()}`);

