// 待审查的钩子代码
class BuggyHook {
  private angle: number = 0;
  private length: number = 0;
  private isFiring: boolean = false;
  private item: any = null;
  private maxAngle: number = 90;
  private maxLength: number = 500;

  update(dt: number) {
    // 摆动
    if (!this.isFiring) {
      this.angle += 2 * dt;
      if (this.angle > this.maxAngle) {
        this.angle = -this.maxAngle;
      }
    }

    // 发射
    if (this.isFiring) {
      this.length += 10 * dt;
      if (this.item) {
        this.length -= 5 * dt; // Bug 1: 同时发射和回收
      }
      if (this.length >= this.maxLength) {
        this.isFiring = false;
        this.length = 0; // Bug 2: 瞬间重置，无回收动画
      }
    }
  }

  fire() {
    this.isFiring = true;
  }

  grabItem(item: any) {
    this.item = item;
    // Bug 3: 未检查当前状态
  }

  getScore() {
    if (this.item) {
      return this.item.value;
    }
    return 0; // Bug 4: 物品价值未清零
  }
}

